      d.innerHTML = `<form method="dialog" class="adm-c"><h2>ADPOSTER v${VERSION}</h2><p>${T('Gestor de cartelería digital: prepara las listas de cada pantalla, compón los carteles y publícalos para que los displays los recojan solos.')}</p><div class="info-comun" id="info-comun"></div><div class="fila"><button type="submit" class="tecla pri">${T('Cerrar')}</button></div></form>`;
